code.source:
def set_age(age):
    if age < 0:
        raise ValueError("age cannot be negative")
    return age
try:
    set_age(-5)
except ValueError as e:
    print("Error:", e)
print(set_age(20))

class BillError(Exception):
    pass
def pay(amount):
    if amount <= 0:
        raise BillError("amount must be positive")
    return amount
try:
    pay(0)
except BillError as e:
    print("Bill problem:", e)

